impl Request {
    /// HTTP method and path of the request, using the most specific URL for the path parameters that are set.
    fn url(&self) -> (crate::http::Method, String) {
        if let Some(index) = &self.index {
            return (
                crate::http::Method::Post,
                format!("/{}/_field_caps", crate::typed::support::path_part(index)),
            );
        }
        (crate::http::Method::Post, "/_field_caps".to_string())
    }

    /// HTTP method of the request.
    pub fn method(&self) -> crate::http::Method {
        self.url().0
    }

    /// Path of the request, with path parameters percent-encoded.
    pub fn path(&self) -> String {
        self.url().1
    }

    /// Query string parameters of the request.
    pub fn query(&self) -> Vec<(&'static str, String)> {
        let mut query = Vec::new();
        if let Some(value) = &self.allow_no_indices {
            query.push((
                "allow_no_indices",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.expand_wildcards {
            query.push((
                "expand_wildcards",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.fields {
            query.push(("fields", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.ignore_unavailable {
            query.push((
                "ignore_unavailable",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.include_unmapped {
            query.push((
                "include_unmapped",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.filters {
            query.push(("filters", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.types {
            query.push(("types", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.include_empty_fields {
            query.push((
                "include_empty_fields",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.error_trace {
            query.push(("error_trace", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.filter_path {
            query.push(("filter_path", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.human {
            query.push(("human", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.pretty {
            query.push(("pretty", crate::typed::support::query_value(value)));
        }
        query
    }

    /// Body of the request.
    pub fn body(&self) -> RequestBody<'_> {
        RequestBody {
            fields2: self.fields2.as_ref(),
            index_filter: self.index_filter.as_ref(),
            runtime_mappings: self.runtime_mappings.as_ref(),
            project_routing: self.project_routing.as_ref(),
        }
    }

    pub(crate) async fn send(
        self,
        client: &crate::Elasticsearch,
    ) -> std::result::Result<Response, crate::Error> {
        use crate::http::{headers::HeaderMap, request::JsonBody};
        let (method, path) = self.url();
        let query = self.query();
        let response = client
            .transport()
            .send(
                method,
                &path,
                HeaderMap::new(),
                Some(&query),
                Some(JsonBody::new(self.body())),
                None,
            )
            .await?
            .error_for_status_code()?;
        response.json().await
    }
}

